"use client";

import { useState } from "react";
import { motion } from "motion/react";
import { Button } from "@/components/ui/button";
import FaqItem from "./FaqItem";
import FaqCategories from "./FaqCategories";
import SearchBox from "./SearchBox";
import { faqData, FaqCategory } from "./data";
 
export default function FaqSection() {
    const [selectedCategory, setSelectedCategory] = useState<FaqCategory>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [showAllFaqs, setShowAllFaqs] = useState(false);

    // Filter FAQs based on selected category and search query
    const filteredFaqs = faqData.filter((faq) => {
        const matchesCategory = selectedCategory === "all" || faq.category === selectedCategory;
        const matchesSearch = faq.question.toLowerCase().includes(searchQuery.toLowerCase()) ||
            faq.answer.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCategory && matchesSearch;
    });
    
    // Determine how many FAQs to display
    const initialFaqCount = 3;
    const displayedFaqs = showAllFaqs ? filteredFaqs : filteredFaqs.slice(0, initialFaqCount);
    const hasMoreFaqs = filteredFaqs.length > initialFaqCount;

    // Get unique categories with their actual counts
    const categories = ["all", ...new Set(faqData.map(faq => faq.category))] as FaqCategory[];
    
    // Count FAQs in each category
    const categoryCounts = categories.reduce((counts, category) => {
        if (category !== "all") {
            counts[category] = faqData.filter(faq => faq.category === category).length;
        } else {
            counts[category] = faqData.length;
        }
        return counts;
    }, {} as Record<string, number>);

    return (
        <section id="faq" 
        className="relative z-10 overflow-hidden flex flex-col items-center justify-center w-full py-12 sm:py-16 md:py-24 px-4 sm:px-6 md:px-10 mx-auto  bg-gray-50/60 dark:bg-neutral-950/50">
            
            
            {/* Section content */}
            <div className="relative z-10 container mx-auto max-w-4xl">
                {/* Header - reduced animation */}
                <div className="mb-8 sm:mb-12 text-center">
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.4 }}
                    >
                        <span className="px-3 py-1 text-xs font-semibold tracking-wider uppercase bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300 rounded-full inline-block mb-3 sm:mb-4">
                            Frequently Asked Questions
                        </span>
                        <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-neutral-900 dark:text-white mb-3 sm:mb-4 tracking-tight">
                            Got <span className="bg-clip-text text-transparent bg-gradient-to-r from-neutral-800 to-black dark:from-neutral-200 dark:to-white">Questions</span>?
                        </h2>
                        <p className="text-base sm:text-lg text-neutral-600 dark:text-neutral-400 max-w-2xl mx-auto">
                            Find answers to common questions about our templates, components, and licensing options.
                        </p>
                    </motion.div>

                    {/* Search box */}
                    <div className="mt-6 sm:mt-8 mb-6 sm:mb-10">
                        <SearchBox
                            searchQuery={searchQuery}
                            setSearchQuery={setSearchQuery}
                        />
                    </div>

                    {/* Categories */}
                    <FaqCategories
                        categories={categories}
                        selectedCategory={selectedCategory}
                        setSelectedCategory={setSelectedCategory}
                        categoryCounts={categoryCounts}
                    />
                </div>

                {/* FAQ items */}
                <div className="flex flex-col gap-3 sm:gap-5">
                    {filteredFaqs.length > 0 ? (
                        <>
                            {displayedFaqs.map((faq, index) => (
                                <FaqItem
                                    key={`faq-${index}`}
                                    question={faq.question}
                                    answer={faq.answer}
                                    category={faq.category}
                                    index={index}
                                />
                            ))}
                            
                            {/* Show More/Less Button */}
                            {hasMoreFaqs && (
                                <motion.div 
                                    className="flex justify-center mt-6"
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    transition={{ duration: 0.3 }}
                                >
                                    <Button 
                                        variant="outline" 
                                        size="sm"
                                        onClick={() => setShowAllFaqs(!showAllFaqs)}
                                        className="flex items-center gap-2 text-xs sm:text-sm"
                                    >
                                        {showAllFaqs ? (
                                            <>
                                                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
                                                </svg>
                                                Show Less
                                            </>
                                        ) : (
                                            <>
                                                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                                </svg>
                                                Show {filteredFaqs.length - initialFaqCount} More
                                            </>
                                        )}
                                    </Button>
                                </motion.div>
                            )}
                        </>
                    ) : (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            transition={{ duration: 0.3 }}
                            className="text-center py-6 sm:py-10"
                        >
                            <p className="text-neutral-500 dark:text-neutral-400">
                                No matching questions found. Try a different search term or category.
                            </p>
                        </motion.div>
                    )}
                </div>

                {/* Contact section - subtler animation */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.4 }}
                    className="mt-10 sm:mt-16 p-4 sm:p-8 rounded-xl border border-neutral-200 dark:border-neutral-700 text-center bg-white/50 dark:bg-neutral-800/50"
                >
                    <h3 className="text-lg sm:text-xl font-semibold text-neutral-900 dark:text-white mb-2">
                        Still have questions?
                    </h3>
                    <p className="text-sm sm:text-base text-neutral-600 dark:text-neutral-400 mb-4 sm:mb-6">
                        {` Can't find the answer you're looking for? Please contact our support team.`}
                    </p>
                    <Button variant="default" className="w-full sm:w-auto"  >
                        <a href="#contact">Contact Support</a>
                    </Button>
                </motion.div>
            </div>
        </section>
    );
}
